#include <stdio.h>
#include <string.h>

int main() {
    int n;
    scanf("%d", &n);

    int a[50] = {1, 2, 4};

    for (int i = 3; i < 50; i++) {
        a[i] = (a[i - 1] + a[i - 2] + a[i - 3]) % 26;
    }

    for (int i = 0; i < n; i++) {
        char s[51];
        scanf("%s", s);

        for (int j = 0; j < strlen(s); j++) {
            s[j] = (char) ((a[j] + s[j] - 97) % 26 + 97);
        }

        puts(s);
    }

    return 0;
}
